#include <stdio.h>

// Partition function: rearranges array elements around a pivot
// Elements smaller than pivot go to the left, larger to the right
// Returns the final index of the pivot element
int partition(int arr[], int low, int high) {
    // Choose the last element as pivot
    int pivot = arr[high];

    // Index of smaller element (indicates rightmost position of smaller elements)
    int i = low - 1;

    // Traverse through all elements
    for (int j = low; j < high; j++) {
        // If current element is smaller than or equal to pivot
        if (arr[j] <= pivot) {
            // Increment index of smaller element
            i++;

            // Swap arr[i] and arr[j]
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    // Place pivot in correct position (after all smaller elements)
    int temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    // Return the partitioning index
    return i + 1;
}

// Quicksort recursive function
// Sorts the array from index low to high
void quicksort(int arr[], int low, int high) {
    // Base case: if subarray has 0 or 1 element, it's already sorted
    if (low < high) {
        // Partition the array and get pivot index
        int pi = partition(arr, low, high);

        // Recursively sort elements before partition
        quicksort(arr, low, pi - 1);

        // Recursively sort elements after partition
        quicksort(arr, pi + 1, high);
    }
}

// Helper function to print array elements
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

// Main function to demonstrate quicksort
int main() {
    // Sample array to sort
    int arr[] = {64, 34, 25, 12, 22, 11, 90};

    // Calculate array size
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("Original array: ");
    printArray(arr, n);

    // Call quicksort to sort the array
    quicksort(arr, 0, n - 1);

    printf("Sorted array: ");
    printArray(arr, n);

    return 0;
}
```

### How Quicksort Works:

1. **Partitioning**: Select a pivot (here, the last element), then rearrange the array so that all elements less than or equal to the pivot are on the left, and greater elements are on the right.

2. **Recursion**: Apply the same process recursively to the left and right subarrays.

3. **Base Case**: When a subarray has 0 or 1 element, it's already sorted.

### Time Complexity:
- **Best/Average Case**: O(n log n)
- **Worst Case**: O(n²) — occurs when the pivot is consistently the smallest or largest element

### Space Complexity:
- **O(log n)** — due to recursive call stack

### Notes:
- This implementation uses the **Lomuto partition scheme**, which is simple and easy to understand.
- For production use, consider optimizations like **randomized pivot selection** or **Hoare's partition scheme** for better performance on certain inputs.
